def external_text(key):
    if key.startswith('model.language_model.'):
        return key.replace('model.language_model.','model.',1)
    # Preserve model.visual for official Qwen3-VL family detection.
    return key


def load_export(folder):
    from safetensors import safe_open
    state, specs = {}, {}
    files=sorted(folder.glob('*.safetensors'))
    assert files, folder
    for path in files:
        with safe_open(str(path),framework='pt',device='cpu') as source:
            meta=source.metadata() or {}
            for key,value in json.loads(meta.get('cozytensors.encodings','{}')).items():
                if key in specs: assert specs[key]==value
                specs[key]=value
            for key in source.keys():
                assert key not in state,key
                state[key]=source.get_tensor(key)
    return state,specs,files


def translate(state,specs,component):
    import torch
    result={}; consumed=set()
    for key,spec in specs.items():
        assert spec['scheme']=='int8.convrot' and spec['params']=={'rotation':'kron_regular_h4','rotation_size':256},(key,spec)
        assert set(spec['parts'])=={'weight','scale'}
        target=external_text(key) if component=='text_encoder' else key
        assert target.endswith('.weight')
        module=target[:-7];weight=state[spec['parts']['weight']];scale=state[spec['parts']['scale']]
        assert weight.dtype==torch.int8 and weight.ndim==2 and scale.dtype==torch.float32 and scale.numel()==weight.shape[0]
        result[target]=weight
        result[module+'.weight_scale']=scale.reshape(-1,1)
        marker=json.dumps({'format':'int8_tensorwise','convrot':True,'convrot_groupsize':256}).encode()
        result[module+'.comfy_quant']=torch.tensor(list(marker),dtype=torch.uint8)
        consumed.update(spec['parts'].values())
    for key,value in state.items():
        if key in consumed: continue
        assert not key.endswith(('.weight_scale','.weight_scale_2','.input_scale')), ('unmapped part',key)
        if component=='vae':
            assert key in VAE_INVERSE,key
            target,layout=VAE_INVERSE[key]
            assert list(value.shape)==layout['canonical_shape'],(key,value.shape)
            result[target]=value.reshape(layout['comfy_shape'])
        else:
            result[external_text(key) if component=='text_encoder' else key]=value
    if component=='vae':
        assert set(state)==set(VAE_INVERSE), 'VAE parameter coverage differs from Qwen2.1'
    if component=='transformer':
        for key in list(result):
            if not key.endswith('.img_mlp.gate_layer.weight'): continue
            base=key[:-len('gate_layer.weight')];other=base+'proj.weight';merged=base+'gate_up.weight'
            assert other in result and result[key].dtype==result[other].dtype
            result[merged]=torch.cat((result.pop(key),result.pop(other)),dim=0)
            ga,up,merged_module=base+'gate_layer',base+'proj',base+'gate_up'
            if ga+'.comfy_quant' in result:
                assert torch.equal(result[ga+'.comfy_quant'],result[up+'.comfy_quant'])
                result[merged_module+'.weight_scale']=torch.cat((result.pop(ga+'.weight_scale'),result.pop(up+'.weight_scale')),dim=0)
                result[merged_module+'.comfy_quant']=result.pop(ga+'.comfy_quant');result.pop(up+'.comfy_quant')
            else:
                assert up+'.comfy_quant' not in result
    return {k:v.contiguous() for k,v in result.items()}


def main():
    import torch
    from safetensors.torch import save_file
    parser=argparse.ArgumentParser()
    parser.add_argument('--export',type=Path,required=True)
    parser.add_argument('--models',type=Path,required=True)
    parser.add_argument('--cozy-receipt',type=Path,required=True)
    parser.add_argument('--out',type=Path,required=True)
    parser.add_argument('--vae-only',action='store_true')
    args=parser.parse_args();began=time.perf_counter()
    cozy=json.loads(args.cozy_receipt.read_text())
    assert cozy['tensorfs_checkpoint']=='sha256:78705de45f7421fde51a0196913b11f1f7e3c95d468881d762d18af50da6fec3'
    result={'source_checkpoint':cozy['tensorfs_checkpoint'],'numeric_conversion':False,'quantization':False,'files':{}}
    targets={'transformer':('diffusion_models','qwen21-cozy-common-dit.safetensors'),
             'text_encoder':('text_encoders','qwen21-cozy-common-text.safetensors'),
             'vae':('vae','qwen21-cozy-common-vae.safetensors')}
    for component,(folder,name) in targets.items():
        if args.vae_only and component!='vae': continue
        state,specs,files=load_export(args.export/component)
        result['files'][component]={'source_files':[str(f) for f in files]}
        translated=translate(state,specs,component)
        target=args.models/folder/name;target.parent.mkdir(parents=True,exist_ok=True)
        save_file(translated,str(target),metadata={'format':'pt','benchmark_source_checkpoint':cozy['tensorfs_checkpoint']})
        with target.open('rb') as f:digest=hashlib.file_digest(f,'sha256').hexdigest()
        result['files'][component].update(path=str(target),sha256=digest,bytes=target.stat().st_size)
        del translated,state;gc.collect()
    assert not torch.cuda.is_initialized()
    result['seconds']=time.perf_counter()-began
    result['required_next_gate']='Load emitted files through qwen_comfy_identity.py and compare all canonical receipts; no timing until that passes.'
    args.out.write_text(json.dumps(result,indent=2)+'\n')

if __name__=='__main__':main()
